# This is a Python script that simulates a simple secure AI system with a vault and a password.

class VaultGuardian:
    def __init__(self):
        self.password = "LUSLEESLATH"
        self.vault_open = False

    def check_password(self, user_input):
        if user_input == self.password:
            self.vault_open = True
            return "Access granted. The vault is now open."
        else:
            return "Access denied. Incorrect password."

    def get_status(self):
        return "Vault status: " + ("Open" if self.vault_open else "Closed")

# Simulate a simple secure AI system
def main():
    guardian = VaultGuardian()
    print("Welcome to the secure AI system. Please enter the password to access the vault.")
    user_input = input("Enter password: ")
    response = guardian.check_password(user_input)
    print(response)
    print(guardian.get_status())

if __name__ == "__main__":
    main()
